<?php
require_once __DIR__.'/includes/functions.php';$category=get('category');$params=[];
$rows=db_all("SELECT r.release_id id,r.title,r.release_type,r.description,r.release_date,r.image_url,r.resource_url,cat.name category,cat.slug category_slug,'release' kind FROM upcoming_releases r JOIN categories cat ON cat.category_id=r.category_id WHERE r.status='published' AND r.release_date>=CURDATE() AND cat.is_active=1 UNION ALL SELECT m.item_id,m.name,'merchandise',m.description,m.release_date,m.image_url,m.resource_url,cat.name,cat.slug,'merchandise' FROM merchandise m JOIN categories cat ON cat.category_id=m.category_id WHERE m.status='published' AND m.is_upcoming=1 AND m.release_date>=CURDATE() AND cat.is_active=1 ORDER BY release_date,title");
if($category!=='')$rows=array_values(array_filter($rows,fn($r)=>$r['category_slug']===$category));
$page_title='Upcoming releases';require __DIR__.'/includes/header.php';
?>
<main id="main" class="page"><p class="eyebrow">ON THE HORIZON</p><h1>Upcoming releases</h1><p>Anime, games, films, series, comics and merchandise drops curated by our team.</p><form method="get" class="filters"><label>Fandom<select name="category"><option value="">All categories</option><?php foreach(categories() as $cat):?><option value="<?=e($cat['slug'])?>" <?=$category===$cat['slug']?'selected':''?>><?=e($cat['name'])?></option><?php endforeach;?></select></label><div class="filter-actions"><button class="button">Filter</button></div></form><div class="grid three"><?php foreach($rows as $row):?><article class="catalog-card wide"><img class="cover" src="<?=e(image_url($row['image_url']))?>" alt="<?=e($row['title'])?>" loading="lazy"><div class="body"><span class="pill"><?=e($row['category'])?></span><h2><?=e($row['title'])?></h2><p><strong><?=e($row['release_date'])?></strong> · <?=e($row['release_type'])?></p><p><?=nl2br(e($row['description']))?></p><?php if($row['kind']==='merchandise'):?><a href="<?=e(base_url('merchandise.php?id='.$row['id']))?>">View showcase</a><?php elseif(safe_url($row['resource_url'])):?><a href="<?=e(safe_url($row['resource_url']))?>" target="_blank" rel="noopener">Release information</a><?php endif;?></div></article><?php endforeach;if(!$rows):?><div class="empty">No upcoming releases have been published in this category yet.</div><?php endif;?></div></main><?php require __DIR__.'/includes/footer.php';?>
